function delay(ms: number): Promise<string> {
  return new Promise(resolve => setTimeout(() => resolve(`Waited ${ms}ms`), ms));
}

function fetchData(id: number): Promise<{ id: number; name: string }> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id > 0) {
        resolve({ id, name: `Item ${id}` });
      } else {
        reject(new Error('Invalid ID'));
      }
    }, 10);
  });
}

async function processItems(): Promise<void> {
  console.log('Start processing');

  const msg = await delay(5);
  console.log(msg);

  try {
    const item = await fetchData(42);
    console.log(`Fetched: ${item.name}`);
  } catch (err) {
    if (err instanceof Error) {
      console.log(`Error: ${err.message}`);
    }
  }

  const [item1, item2] = await Promise.all([
    fetchData(1),
    fetchData(2)
  ]);
  console.log(`Batch: ${item1.name}, ${item2.name}`);

  console.log('Done');
}

processItems().catch(console.error);
